mapper.select:
SELECT id, project_type, project_level, delivery_name, delivery_category, stage, required, trigger_tr, acceptance_criteria, template_ref, remark, tenant_id, provider_trace_id, created_at, updated_at, deleted FROM pmis_execution_delivery_standard
deleted = 0
AND project_type = #{projectType}
AND (project_level = #{projectLevel} OR project_level IS NULL OR project_level = '')
AND stage = #{stage}
ORDER BY id
